INSERT INTO "workflow_template" ("id", "name", "description", "category", "language", "minPlan", "published", "nodes", "connections", "nodeTypes", "useCount", "createdById", "createdAt", "updatedAt")
VALUES ('tpl_starter_instagram_comment_to_dm_en', 'Instagram comment to DM: leads in Google Sheets', 'When someone comments a keyword such as PRICE under your post or reel, they get a private message from you at once, a public reply so others see you answered, and a row in your Google Sheet with their user name, comment and the post. Set up: put the Verify Token and App Secret on the Instagram Trigger and subscribe your Meta app''s Instagram webhook to comments; change the keywords on the trigger; pick your Instagram credential on both Instagram nodes and write your own message; pick a Google credential and your sheet on Google Sheets (columns: Date, User name, User ID, Comment, Post).', 'Marketing', 'en', 'FREE', true, '[{"id":"tpl_starter_instagram_comment_to_dm_en_trigger","type":"INSTAGRAM_TRIGGER","position":{"x":0,"y":0},"data":{"triggerOn":"comments","keywords":"price, info, details"}},{"id":"tpl_starter_instagram_comment_to_dm_en_dm","type":"INSTAGRAM","position":{"x":320,"y":0},"data":{"variableName":"dm","operation":"private_reply","connection":"facebook","commentId":"{{instagram.commentId}}","message":"Hi {{instagram.fromName}}, thanks for your comment! Here are the prices and details (replace with your own): ... Reply to this message with any question and we will help you."}},{"id":"tpl_starter_instagram_comment_to_dm_en_publicReply","type":"INSTAGRAM","position":{"x":640,"y":0},"data":{"variableName":"publicReply","operation":"reply_comment","connection":"facebook","commentId":"{{instagram.commentId}}","message":"Thanks! We have sent you a DM with the details."}},{"id":"tpl_starter_instagram_comment_to_dm_en_saveLead","type":"GOOGLE_SHEETS","position":{"x":960,"y":0},"data":{"variableName":"savedLead","operation":"append","sheetId":"","sheetName":"Sheet1","rowData":"{{ $now }}, {{instagram.fromName}}, {{instagram.from}}, {{instagram.text}}, {{instagram.postId}}"}}]'::jsonb, '[{"fromNodeId":"tpl_starter_instagram_comment_to_dm_en_trigger","toNodeId":"tpl_starter_instagram_comment_to_dm_en_dm","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_starter_instagram_comment_to_dm_en_dm","toNodeId":"tpl_starter_instagram_comment_to_dm_en_publicReply","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_starter_instagram_comment_to_dm_en_publicReply","toNodeId":"tpl_starter_instagram_comment_to_dm_en_saveLead","fromOutput":"source-1","toInput":"target-1"}]'::jsonb, ARRAY['INSTAGRAM_TRIGGER', 'INSTAGRAM', 'GOOGLE_SHEETS']::text[], 0, 'system', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
